-- Migration 22: Entra audit log exports downloaded from the portal (CSV and JSON) load into directory_audits. The CSV has
-- no audit id and stops at 3 targets x 5 properties and 6 details, so rows now say how complete they are. Existing rows
-- keep NULL until their file is ingested again; nothing is rewritten.
ALTER TABLE directory_audits ADD COLUMN data_completeness data_completeness;

COMMENT ON TABLE directory_audits IS 'Entra ID directory audit events: Hawk EntraIDAuditLogs (JSON preferred over the CSV, whose nested columns are .NET type names), Microsoft-Extractor-Suite Get-GraphEntraAuditLogs JSON, and the Entra admin center audit log download (JSON, or CSV). One row per audit id; later copies only fill NULL columns. A portal CSV row has no audit id: its record_key is csvrow: plus a hash of its cells, so the same CSV event downloaded twice is one row, while the JSON copy of that event is a separate row (the CSV carries nothing to match it on).';
COMMENT ON COLUMN directory_audits.record_key IS 'Audit id, lower-case. For a portal CSV row (no audit id): csvrow: followed by the SHA-256 hex of its non-empty cells sorted by lower-case header, each written as <byte length of header>:<header><byte length of value>:<value>.';
COMMENT ON COLUMN directory_audits.audit_id IS 'Audit event Id, lower-case. NULL for portal CSV rows, which have no Id column.';
COMMENT ON COLUMN directory_audits.targets IS 'TargetResources as collected (Graph camelCase for portal CSV rows: type, displayName, id, userPrincipalName, modifiedProperties; targets whose cells are all empty are left out).';
COMMENT ON COLUMN directory_audits.initiated_by_app_id IS 'InitiatedBy.App.AppId, lower-case. NULL for portal CSV rows: the CSV gives the service principal id, not the AppId.';
COMMENT ON COLUMN directory_audits.data_completeness IS 'Completeness of the FIRST copy loaded, never rewritten (evidence is not overwritten): full for JSON sources (portal, Invictus, Hawk); partial for CSV (portal CSV stops at 3 targets x 5 modified properties and 6 additional details; Hawk CSV nested columns are .NET type names). Columns that first copy left NULL may have been filled later by a fuller copy of the same Id (column_collections names the collection that supplied each column), so a partial row can hold values from a full copy. NULL for rows loaded before schema 22 until their file is ingested again.';
